-- BATTLECRUISER M20 — Caja + Reinversiones + integración de gastos
-- Aplicación: 2026-08-22
-- Fuente de verdad: producción fue introspectada antes de aplicar.

ALTER TABLE public.permisos DROP CONSTRAINT IF EXISTS permisos_seccion_check;
ALTER TABLE public.permisos ADD CONSTRAINT permisos_seccion_check CHECK (seccion = ANY (ARRAY['productos','categorias','almacenes','stock','transferencias','vales_salida','ventas','reportes','usuarios','presentaciones','auditoria','turnos','comunicacion','unidades','ciclos','entregas_caja','gastos','mermas','bajas','reinversiones']));

CREATE TABLE IF NOT EXISTS public.reinversiones (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), almacen_id uuid NOT NULL REFERENCES public.almacenes(id), ciclo_id uuid REFERENCES public.ciclos_operativos(id), sesion_id uuid REFERENCES public.sesiones_ciclo(id), turno_id uuid REFERENCES public.turnos(id), proveedor text, fecha timestamptz NOT NULL DEFAULT now(), total numeric(12,2) NOT NULL DEFAULT 0 CHECK(total>=0), usuario_id uuid REFERENCES public.usuarios(id), usuario_nombre text, idempotency_key uuid NOT NULL UNIQUE, creado_en timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.reinversiones_lineas (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reinversion_id uuid NOT NULL REFERENCES public.reinversiones(id) ON DELETE CASCADE, producto_id uuid NOT NULL REFERENCES public.productos(id), presentacion_id uuid REFERENCES public.presentaciones(id), cantidad_presentacion numeric(12,3), cantidad_base numeric(12,3) NOT NULL CHECK(cantidad_base>0), costo_total numeric(12,2) NOT NULL CHECK(costo_total>0), costo_unitario numeric(12,6) NOT NULL CHECK(costo_unitario>=0)
);
CREATE TABLE IF NOT EXISTS public.movimientos_caja (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), almacen_id uuid REFERENCES public.almacenes(id), ciclo_id uuid REFERENCES public.ciclos_operativos(id), sesion_id uuid REFERENCES public.sesiones_ciclo(id), turno_id uuid REFERENCES public.turnos(id), tipo text NOT NULL CHECK(tipo IN('GASTO','REINVERSION','AJUSTE')), direccion text NOT NULL CHECK(direccion IN('ENTRADA','SALIDA')), monto numeric(12,2) NOT NULL CHECK(monto>0), referencia_tipo text NOT NULL, referencia_id uuid NOT NULL, concepto text NOT NULL, creado_por uuid REFERENCES public.usuarios(id), creado_nombre text, creado_en timestamptz NOT NULL DEFAULT now(), UNIQUE(referencia_tipo,referencia_id)
);
CREATE INDEX IF NOT EXISTS idx_movimientos_caja_almacen_fecha ON public.movimientos_caja(almacen_id,creado_en DESC);
CREATE INDEX IF NOT EXISTS idx_movimientos_caja_turno ON public.movimientos_caja(turno_id,creado_en DESC);
CREATE INDEX IF NOT EXISTS idx_reinversiones_fecha ON public.reinversiones(fecha DESC);
ALTER TABLE public.reinversiones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reinversiones_lineas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.movimientos_caja ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.reinversiones,public.reinversiones_lineas,public.movimientos_caja FROM anon,authenticated;

ALTER TABLE public.lotes_compra DROP CONSTRAINT IF EXISTS lotes_compra_origen_check;
ALTER TABLE public.lotes_compra ADD CONSTRAINT lotes_compra_origen_check CHECK (origen = ANY (ARRAY['compra'::text,'transferencia'::text,'reinversion'::text]));

CREATE OR REPLACE FUNCTION private.registrar_movimiento_caja(p_almacen_id uuid,p_ciclo_id uuid,p_sesion_id uuid,p_turno_id uuid,p_tipo text,p_direccion text,p_monto numeric,p_referencia_tipo text,p_referencia_id uuid,p_concepto text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','private','pg_temp' AS $$ DECLARE v_id uuid;v_nombre text; BEGIN IF p_monto IS NULL OR p_monto<=0 THEN RAISE EXCEPTION 'Monto de caja inválido'; END IF; SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=auth.uid(); SELECT id INTO v_id FROM public.movimientos_caja WHERE referencia_tipo=p_referencia_tipo AND referencia_id=p_referencia_id FOR UPDATE; IF v_id IS NOT NULL THEN RETURN v_id; END IF; INSERT INTO public.movimientos_caja(almacen_id,ciclo_id,sesion_id,turno_id,tipo,direccion,monto,referencia_tipo,referencia_id,concepto,creado_por,creado_nombre) VALUES(p_almacen_id,p_ciclo_id,p_sesion_id,p_turno_id,p_tipo,p_direccion,p_monto,p_referencia_tipo,p_referencia_id,p_concepto,auth.uid(),v_nombre) RETURNING id INTO v_id; RETURN v_id; END; $$;

CREATE OR REPLACE FUNCTION public.registrar_reinversion_multiple(p_almacen_id uuid,p_proveedor text DEFAULT NULL,p_fecha timestamptz DEFAULT now(),p_lineas jsonb DEFAULT '[]'::jsonb,p_ciclo_id uuid DEFAULT NULL,p_sesion_id uuid DEFAULT NULL,p_turno_id uuid DEFAULT NULL,p_idempotency_key uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','private','pg_temp' AS $$ DECLARE v_uid uuid:=auth.uid();v_id uuid;v_linea jsonb;v_prod uuid;v_pres uuid;v_qty_pres numeric;v_qty numeric;v_cost_total numeric;v_unit numeric;v_total numeric:=0;v_nombre text;v_exist uuid;v_turno uuid:=p_turno_id;v_alm uuid:=p_almacen_id;v_ciclo uuid:=p_ciclo_id;v_sesion uuid:=p_sesion_id;v_turn_alm uuid;v_turn_ciclo uuid;v_turn_sesion uuid; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'No hay sesión activa.' USING errcode='42501'; END IF; IF NOT public.tiene_permiso('reinversiones','crear') THEN RAISE EXCEPTION 'Sin permiso para registrar reinversiones' USING errcode='42501'; END IF; IF p_idempotency_key IS NULL THEN RAISE EXCEPTION 'Se requiere idempotency_key'; END IF; IF p_lineas IS NULL OR jsonb_array_length(p_lineas)=0 THEN RAISE EXCEPTION 'La reinversión debe tener al menos un producto'; END IF; IF NOT EXISTS(select 1 from public.almacenes where id=p_almacen_id) THEN RAISE EXCEPTION 'Almacén no encontrado'; END IF; SELECT id INTO v_exist FROM public.reinversiones WHERE idempotency_key=p_idempotency_key AND usuario_id=v_uid; IF v_exist IS NOT NULL THEN RETURN v_exist; END IF; IF v_turno IS NULL THEN SELECT t.id,t.almacen_id,t.ciclo_id,t.sesion_id INTO v_turno,v_turn_alm,v_turn_ciclo,v_turn_sesion FROM public.turnos t WHERE t.usuario_id=v_uid AND t.estado='ABIERTO' AND t.almacen_id=p_almacen_id ORDER BY t.apertura_real DESC NULLS LAST LIMIT 1; IF v_turno IS NOT NULL THEN v_alm:=coalesce(v_turn_alm,v_alm);v_ciclo:=coalesce(v_turn_ciclo,v_ciclo);v_sesion:=coalesce(v_turn_sesion,v_sesion); END IF; END IF; SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=v_uid; INSERT INTO public.reinversiones(almacen_id,ciclo_id,sesion_id,turno_id,proveedor,fecha,usuario_id,usuario_nombre,idempotency_key) VALUES(v_alm,v_ciclo,v_sesion,v_turno,NULLIF(trim(p_proveedor),''),coalesce(p_fecha,now()),v_uid,v_nombre,p_idempotency_key) RETURNING id INTO v_id; FOR v_linea IN SELECT * FROM jsonb_array_elements(p_lineas) LOOP v_prod:=nullif(v_linea->>'producto_id','')::uuid;v_pres:=nullif(v_linea->>'presentacion_id','')::uuid;v_qty_pres:=nullif(v_linea->>'cantidad_presentacion','')::numeric;v_cost_total:=nullif(v_linea->>'costo_total','')::numeric; IF v_prod IS NULL OR v_cost_total IS NULL OR v_cost_total<=0 THEN RAISE EXCEPTION 'Producto y costo total son obligatorios en cada línea'; END IF; IF NOT EXISTS(select 1 from public.productos where id=v_prod) THEN RAISE EXCEPTION 'Producto no encontrado: %',v_prod; END IF; IF v_pres IS NOT NULL THEN SELECT unidades_base INTO v_qty FROM public.obtener_conversion_presentacion(v_prod,v_pres,v_qty_pres); ELSE v_qty:=nullif(v_linea->>'cantidad_base','')::numeric; END IF; IF v_qty IS NULL OR v_qty<=0 THEN RAISE EXCEPTION 'Cantidad inválida en línea de reinversión'; END IF; v_unit:=v_cost_total/v_qty; INSERT INTO public.reinversiones_lineas(reinversion_id,producto_id,presentacion_id,cantidad_presentacion,cantidad_base,costo_total,costo_unitario) VALUES(v_id,v_prod,v_pres,v_qty_pres,v_qty,v_cost_total,v_unit); INSERT INTO public.lotes_compra(producto_id,almacen_id,cantidad_inicial,cantidad_restante,costo_unitario,fecha_compra,origen,usuario_id,compra_id) VALUES(v_prod,v_alm,v_qty,v_qty,v_unit,coalesce(p_fecha,now()),'reinversion',v_uid,NULL); INSERT INTO public.stock(producto_id,almacen_id,cantidad,minimo) VALUES(v_prod,v_alm,v_qty,0) ON CONFLICT(producto_id,almacen_id) DO UPDATE SET cantidad=public.stock.cantidad+excluded.cantidad,updated_at=now(); v_total:=v_total+v_cost_total; END LOOP; IF v_total<=0 THEN RAISE EXCEPTION 'La reinversión debe tener un total mayor que cero'; END IF; UPDATE public.reinversiones SET total=v_total WHERE id=v_id; PERFORM private.registrar_movimiento_caja(v_alm,v_ciclo,v_sesion,v_turno,'REINVERSION','SALIDA',v_total,'reinversion',v_id,coalesce(nullif(trim(p_proveedor),''),'Reinversión de inventario')); RETURN v_id; END; $$;

CREATE OR REPLACE FUNCTION public.listar_reinversiones(p_almacen_id uuid DEFAULT NULL,p_desde date DEFAULT NULL,p_hasta date DEFAULT NULL,p_limite integer DEFAULT 50,p_offset integer DEFAULT 0) RETURNS TABLE(id uuid,almacen_id uuid,almacen_nombre text,proveedor text,fecha timestamptz,total numeric,usuario_nombre text,lineas jsonb) LANGUAGE sql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ SELECT r.id,r.almacen_id,a.nombre,r.proveedor,r.fecha,r.total,r.usuario_nombre,coalesce((select jsonb_agg(jsonb_build_object('producto_id',l.producto_id,'producto_nombre',p.nombre,'presentacion_id',l.presentacion_id,'cantidad_presentacion',l.cantidad_presentacion,'cantidad_base',l.cantidad_base,'costo_total',l.costo_total,'costo_unitario',l.costo_unitario) order by l.id) from public.reinversiones_lineas l join public.productos p on p.id=l.producto_id where l.reinversion_id=r.id),'[]'::jsonb) FROM public.reinversiones r join public.almacenes a on a.id=r.almacen_id WHERE (p_almacen_id IS NULL OR r.almacen_id=p_almacen_id) AND (p_desde IS NULL OR r.fecha::date>=p_desde) AND (p_hasta IS NULL OR r.fecha::date<=p_hasta) ORDER BY r.fecha DESC LIMIT greatest(coalesce(p_limite,50),1) OFFSET greatest(coalesce(p_offset,0),0); $$;

CREATE OR REPLACE FUNCTION public.listar_movimientos_caja(p_almacen_id uuid DEFAULT NULL,p_desde date DEFAULT NULL,p_hasta date DEFAULT NULL,p_limite integer DEFAULT 100,p_offset integer DEFAULT 0) RETURNS TABLE(id uuid,fecha timestamptz,tipo text,direccion text,monto numeric,almacen_nombre text,concepto text,usuario_nombre text,referencia_tipo text,referencia_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ SELECT m.id,m.creado_en,m.tipo,m.direccion,m.monto,a.nombre,m.concepto,m.creado_nombre,m.referencia_tipo,m.referencia_id FROM public.movimientos_caja m LEFT JOIN public.almacenes a ON a.id=m.almacen_id WHERE (p_almacen_id IS NULL OR m.almacen_id=p_almacen_id) AND (p_desde IS NULL OR m.creado_en::date>=p_desde) AND (p_hasta IS NULL OR m.creado_en::date<=p_hasta) ORDER BY m.creado_en DESC LIMIT greatest(coalesce(p_limite,100),1) OFFSET greatest(coalesce(p_offset,0),0); $$;

-- El gasto aprobado descuenta caja atómicamente; las mermas/bajas siguen afectando stock solo al aprobar.
-- La versión completa de resolver_aprobacion_operativa en producción incluye este comportamiento.
CREATE OR REPLACE FUNCTION public.resolver_aprobacion_operativa(p_tipo text,p_id uuid,p_decision text,p_comentario text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','private','pg_temp' AS $$ DECLARE v_nombre text;v_alm uuid;v_prod uuid;v_cant numeric;v_estado text;v_gasto record; BEGIN IF NOT(public.tiene_permiso('auditoria','editar_any') OR public.tiene_permiso('gastos','editar_any') OR public.tiene_permiso('mermas','editar_any') OR public.tiene_permiso('bajas','editar_any')) THEN RAISE EXCEPTION 'Sin permiso administrativo para aprobar operaciones'; END IF; IF p_decision NOT IN('APROBAR','RECHAZAR') THEN RAISE EXCEPTION 'Decisión inválida'; END IF; IF p_decision='RECHAZAR' AND(p_comentario IS NULL OR btrim(p_comentario)='') THEN RAISE EXCEPTION 'El rechazo requiere un motivo'; END IF; SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=auth.uid(); IF p_tipo='gasto' THEN SELECT * INTO v_gasto FROM public.gastos WHERE id=p_id FOR UPDATE; IF v_gasto.id IS NULL OR v_gasto.estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Gasto no pendiente o inexistente'; END IF; IF p_decision='APROBAR' THEN PERFORM private.registrar_movimiento_caja(v_gasto.almacen_id,v_gasto.ciclo_id,v_gasto.sesion_id,NULL,'GASTO','SALIDA',v_gasto.monto,'gasto',v_gasto.id,v_gasto.concepto); END IF; UPDATE public.gastos SET estado=CASE WHEN p_decision='APROBAR' THEN 'APROBADO' ELSE 'RECHAZADO' END,revisado_por=auth.uid(),revisado_nombre=v_nombre,comentario_revision=NULLIF(btrim(p_comentario),''),fecha_revision=now(),actualizado_en=now() WHERE id=p_id; ELSIF p_tipo='merma' THEN SELECT estado,almacen_id,producto_id,cantidad INTO v_estado,v_alm,v_prod,v_cant FROM public.mermas WHERE id=p_id FOR UPDATE; IF v_estado IS NULL OR v_estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Merma no pendiente o inexistente'; END IF; IF p_decision='APROBAR' THEN PERFORM public._aplicar_salida_aprobada(v_alm,v_prod,v_cant); END IF; UPDATE public.mermas SET estado=CASE WHEN p_decision='APROBAR' THEN 'APROBADA' ELSE 'RECHAZADA' END,revisado_por=auth.uid(),revisado_nombre=v_nombre,comentario_revision=NULLIF(btrim(p_comentario),''),fecha_revision=now(),actualizado_en=now() WHERE id=p_id; ELSIF p_tipo='baja' THEN SELECT estado,almacen_id,producto_id,cantidad INTO v_estado,v_alm,v_prod,v_cant FROM public.bajas WHERE id=p_id FOR UPDATE; IF v_estado IS NULL OR v_estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Baja no pendiente o inexistente'; END IF; IF p_decision='APROBAR' THEN PERFORM public._aplicar_salida_aprobada(v_alm,v_prod,v_cant); END IF; UPDATE public.bajas SET estado=CASE WHEN p_decision='APROBAR' THEN 'APROBADA' ELSE 'RECHAZADA' END,revisado_por=auth.uid(),revisado_nombre=v_nombre,comentario_revision=NULLIF(btrim(p_comentario),''),fecha_revision=now(),actualizado_en=now() WHERE id=p_id; ELSE RAISE EXCEPTION 'Tipo de aprobación desconocido'; END IF; RETURN jsonb_build_object('ok',true,'tipo',p_tipo,'id',p_id,'decision',p_decision,'revisado_por',v_nombre); END; $$;

CREATE OR REPLACE FUNCTION public.calcular_dinero_esperado_turno(p_turno_id uuid) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','private','pg_temp' AS $$ DECLARE t record;total numeric:=0;hasta timestamptz;BEGIN SELECT * INTO t FROM public.turnos WHERE id=p_turno_id;IF t.id IS NULL THEN RETURN 0;END IF;hasta:=coalesce(t.cierre_real,now());SELECT coalesce(sum(v.total),0) INTO total FROM public.ventas v WHERE v.fecha>=t.apertura_real AND v.fecha<=hasta AND v.creado_por=t.usuario_id AND (t.almacen_id IS NULL OR v.almacen_id=t.almacen_id);total:=total-coalesce((SELECT sum(m.monto) FROM public.movimientos_caja m WHERE m.turno_id=p_turno_id AND m.direccion='SALIDA'),0);RETURN greatest(total,0);END; $$;

-- crear_gasto conserva el flujo M19 y, cuando existe un turno abierto del usuario, lo asocia automáticamente.
CREATE OR REPLACE FUNCTION public.crear_gasto(p_concepto text,p_monto numeric,p_descripcion text DEFAULT NULL,p_almacen_id uuid DEFAULT NULL,p_ciclo_id uuid DEFAULT NULL,p_sesion_id uuid DEFAULT NULL,p_idempotency_key uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ DECLARE v_id uuid;v_nombre text;v_turno uuid;v_alm uuid:=p_almacen_id;v_ciclo uuid:=p_ciclo_id;v_sesion uuid:=p_sesion_id;BEGIN IF NOT public.tiene_permiso('gastos','crear') THEN RAISE EXCEPTION 'Sin permiso para registrar gastos';END IF;IF p_concepto IS NULL OR btrim(p_concepto)='' OR p_monto IS NULL OR p_monto<=0 THEN RAISE EXCEPTION 'Concepto y monto válidos son obligatorios';END IF;IF p_idempotency_key IS NOT NULL AND EXISTS(SELECT 1 FROM public.gastos WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid()) THEN SELECT id INTO v_id FROM public.gastos WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid() LIMIT 1;RETURN v_id;END IF;SELECT t.id,t.almacen_id,t.ciclo_id,t.sesion_id INTO v_turno,v_alm,v_ciclo,v_sesion FROM public.turnos t WHERE t.usuario_id=auth.uid() AND t.estado='ABIERTO' AND (p_almacen_id IS NULL OR t.almacen_id=p_almacen_id) ORDER BY t.apertura_real DESC NULLS LAST LIMIT 1;SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=auth.uid();INSERT INTO public.gastos(concepto,monto,descripcion,almacen_id,ciclo_id,sesion_id,creado_por,creado_nombre,idempotency_key) VALUES(btrim(p_concepto),p_monto,NULLIF(btrim(p_descripcion),''),v_alm,v_ciclo,v_sesion,auth.uid(),v_nombre,p_idempotency_key) RETURNING id INTO v_id;RETURN v_id;END; $$;

INSERT INTO public.permisos(role_id,seccion,accion,permitido) SELECT r.id,s.seccion,s.accion,true FROM public.roles r CROSS JOIN (VALUES('reinversiones','ver'),('reinversiones','crear')) s(seccion,accion) WHERE lower(r.nombre) IN('dueño','admin','administrador') ON CONFLICT(role_id,seccion,accion) DO UPDATE SET permitido=EXCLUDED.permitido;
INSERT INTO public.permisos(role_id,seccion,accion,permitido) SELECT r.id,'reinversiones','crear',true FROM public.roles r WHERE lower(r.nombre) NOT IN('dueño','admin','administrador') AND EXISTS(SELECT 1 FROM public.permisos p WHERE p.role_id=r.id AND p.seccion='gastos' AND p.accion='crear' AND p.permitido=true) ON CONFLICT(role_id,seccion,accion) DO UPDATE SET permitido=EXCLUDED.permitido;

REVOKE ALL ON FUNCTION public.registrar_reinversion_multiple(uuid,text,timestamptz,jsonb,uuid,uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.registrar_reinversion_multiple(uuid,text,timestamptz,jsonb,uuid,uuid,uuid,uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.listar_reinversiones(uuid,date,date,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.listar_reinversiones(uuid,date,date,integer,integer) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.listar_movimientos_caja(uuid,date,date,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.listar_movimientos_caja(uuid,date,date,integer,integer) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.calcular_dinero_esperado_turno(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.calcular_dinero_esperado_turno(uuid) TO authenticated,service_role;
